command:
set -euo pipefail
git log --no-merges --format='@@@%H%x09%ad%x09%s' --date=short --numstat d33c62eebc48de5e8a65c50e057addf25f125c6b..51e7faddad943ab7727e407d008e474ec076566d |
awk '
function flush() {if (seen) printf "%d\t%d\t%d\t%d\t%s\t%s\t%s\n", add+del, add, del, files, hash, date, subject}
$0 ~ /^@@@/ {flush(); seen=1; line=substr($0,4); split(line,a,"\t"); hash=a[1]; date=a[2]; subject=a[3]; for(i=4;i<=length(a);i++) subject=subject "\t" a[i]; add=del=files=0; next}
$1 ~ /^[0-9]+$/ && $2 ~ /^[0-9]+$/ {add+=$1; del+=$2; files++}
END {flush()}' | sort -nr -k1,1 | sed -n '1,40p'

